24	        private void sort() {
25	            int[] source = scratch;
26	            int[] target = values;
27	
28	            for (int width = 1; width < values.length; width *= 2) {
29	                mergePass(source, target, width);
30	
31	                int[] nextSource = target;
32	                target = source;
33	                source = nextSource;
