49	        private void mergeRange(int[] source, int[] target, int start, int middle, int end) {
50	            int leftIndex = start;
51	            int rightIndex = middle;
52	            int targetIndex = start;
53	
54	            while (leftIndex < middle && rightIndex < end) {
55	                if (source[leftIndex] <= source[rightIndex]) {
56	                    target[targetIndex++] = source[leftIndex++];
57	                } else {
58	                    target[targetIndex++] = source[rightIndex++];
